// Parse incoming data from MagdalenaBot
const input = items[0].json;

// Extract email and station info
const email = input.email;
const stationName = input.station_name;
const stationCode = input.station_code;
const analysisType = input.analysis_type;
const csvs = input.csvs || {};

// Prepare CSV attachments
const attachments = [];

for (const [name, csvContent] of Object.entries(csvs)) {
  // Convert CSV string to base64
  const base64Content = Buffer.from(csvContent, 'utf-8').toString('base64');

  attachments.push({
    name: `${stationCode}_${name}.csv`,
    content: base64Content,
    encoding: 'base64',
    mimetype: 'text/csv'
  });
}

// Generate email subject
const subject = `[MagdalenaBot] Análisis Hidrológico - ${stationName} (${analysisType})`;

// Generate email body
const body = generateEmailBody(stationName, stationCode, analysisType, input.metadata);

return [{
  json: {
    email,
    subject,
    body,
    attachments,
    stationName,
    stationCode
  }
}];

