      <p><strong>Años de datos:</strong> ${metadata.years_of_data || 'N/A'}</p>
      <p><strong>Nivel mínimo:</strong> ${metadata.level_min_cm || 'N/A'} cm</p>
      <p><strong>Nivel máximo:</strong> ${metadata.level_max_cm || 'N/A'} cm</p>
      <p><strong>Nivel promedio:</strong> ${metadata.level_mean_cm || 'N/A'} cm</p>
