// Validate input
const input = items[0].json;
const errors = [];

if (!input.email) errors.push('Missing email');
if (!input.station_code) errors.push('Missing station_code');
if (!input.station_name) errors.push('Missing station_name');
if (!input.analysis_type) errors.push('Missing analysis_type');
if (!input.csvs || Object.keys(input.csvs).length === 0) errors.push('Missing CSVs');

if (errors.length > 0) {
  return [{
    json: {
      success: false,
      errors: errors,
      message: 'Validation failed'
    }
  }];
}

return [{
  json: {
    success: true,
    data: input
  }
}];

// Log the request for debugging
const input = items[0].json;
console.log('MagdalenaBot Request:', {
  timestamp: new Date().toISOString(),
  station: input.station_name,
  code: input.station_code,
  analysis: input.analysis_type,
  email: input.email
});
return items;
